20	/*!
21	 * \file inject_software_pipeline.cc
22	 * \brief Transform annotated loops into pipelined one that parallelize
23	 * producers and consumers
24	 */
25	#include <tvm/target/target.h>
26	#include <tvm/tir/builtin.h>
27	#include <tvm/tir/transform.h>
28	
29	#include <unordered_set>
30	
31	#include "support/utils.h"
32	#include "tir/schedule/utils.h"
33	#include "tir/transforms/ir_utils.h"
