35	namespace tvm {
36	namespace tl {
37	using namespace tir;
38	
39	/*!
40	 * \brief Create a block and infer the access region with the given body.
41	 *
42	 * The result is a opaque block that doesn't contain any block iter vars. In
43	 * case the body is a block realize without predicate, it is unnecessary to
44	 * create a new block, the block of the block realize will be returned.
45	 *
46	 * \param body The body of the block.
47	 * \param buffer_data_to_buffer The map from buffer data to buffer.
48	 * \return The result block.
49	 */
50	Block MakeBlock(const Stmt &body,
51	                const Map<Var, Buffer> &buffer_data_to_buffer) {
52	  if (const BlockRealizeNode *block_realize = body.as<BlockRealizeNode>()) {
53	    if (is_one(block_realize->predicate)) {
54	      // no need to create a new block
55	      return block_realize->block;
56	    }
57	  }
58	  Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{}, /*name_hint=*/"",
59	              /*body*/ body);
60	  Array<Array<BufferRegion>> access =
61	      GetBlockReadWriteRegion(block, buffer_data_to_buffer);
62	  BlockNode *n = block.CopyOnWrite();
63	  n->reads = access[0];
64	  n->writes = access[1];
65	  return block;
66	}
67	
68	/*! Structure that represents the provided annotation per block or loop. */
69	struct PipelineAnnotation {
70	  int stage;
71	  int order;
72	  bool async;
73	};
74	
75	using PipelineInfo = std::unordered_map<Block, PipelineAnnotation,
76	                                        ObjectPtrHash, ObjectPtrEqual>;
77	
78	struct BufferAccessInfo {
79	  int def = -1; // the defining stage of the buffer
80	  int use = -1; // the last using stage of the buffer
81	};
82	
83	/*!
84	 * \brief Replace IfThenElse nodes with their then_case, preserving attribute
85	 * nodes \param body The statement to process \param condition The condition to
86	 * match in IfThenElse nodes \return The transformed statement
87	 */
88	Stmt replace_if_then_else(Stmt body, PrimExpr condition) {
89	  if (const auto *if_node = body.as<IfThenElseNode>()) {
90	    // If this is an IfThenElse with the matching condition, replace it with its
91	    // then_case
92	    if (if_node->condition.same_as(condition)) {
93	      return if_node->then_case;
94	    }
95	  } else if (const auto *attr_node = body.as<AttrStmtNode>()) {
96	    // For attribute nodes, preserve the attribute but process its body
97	    AttrStmt attr_stmt = GetRef<AttrStmt>(attr_node);
98	    attr_stmt.CopyOnWrite()->body =
99	        replace_if_then_else(attr_node->body, condition);
100	    return attr_stmt;
101	  } else if (const auto *block_node = body.as<BlockNode>()) {
102	    // For block nodes, process the body
103	    Block block = GetRef<Block>(block_node);
104	    block.CopyOnWrite()->body =
105	        replace_if_then_else(block_node->body, condition);
106	    return block;
107	  }
108	  // For any other node type, return it unchanged
109	  return body;
110	}
