112	/*!
113	 * \brief Rewriter for the body of the software pipeline. This pass inserts
114	 * `floormod` to indices of the remapped buffer to select the version
115	 * corresponding to the pipeline stage.
116	 */
117	class PipelineBodyRewriter : public StmtExprMutator {
118	public:
119	  /*!
120	   * \brief Constructor of PipelineBodyRewriter.
121	   * \param buffer_data_to_buffer The map from buffer data to buffer.
122	   * \param buffer_remap The map from original buffer to the buffer with updated
123	   * shape for multi-versioning in the software pipeline. \param pipeline_loop
124	   * The original loop to be software pipelined. \param access_all_versions
125	   * Whether all versions the buffers in the software pipeline are accessed.
126	   * This will be used to update block access region. In the prologue and
127	   * epilogue of a two-stage software pipeline, only one version of these
128	   * buffers are accessed.
129	   */
130	  PipelineBodyRewriter(const Map<Var, Buffer> &buffer_data_to_buffer,
131	                       const Map<Buffer, Buffer> &buffer_remap,
132	                       For pipeline_loop, bool access_all_versions)
133	      : buffer_data_to_buffer_(buffer_data_to_buffer),
134	        buffer_remap_(buffer_remap), pipeline_loop_(pipeline_loop),
135	        access_all_versions_(access_all_versions) {}
136	
137	private:
138	  BufferRegion
139	  RewritePipelineBufferRegion(const BufferRegion &buffer_region) const {
140	    auto it = buffer_remap_.find(buffer_region->buffer);
141	    if (it != buffer_remap_.end()) {
142	      Region new_region = buffer_region->region;
143	      const Buffer &new_buffer = (*it).second;
144	      // For pipeline buffers, relax the access region of the first dimension to
145	      // full extent if access_all_versions == true
146	      Range accessed_version =
147	          access_all_versions_
148	              ? Range::FromMinExtent(0, new_buffer->shape[0])
149	              : Range::FromMinExtent(
150	                    floormod((pipeline_loop_->loop_var - pipeline_loop_->min),
151	                             new_buffer->shape[0]),
152	                    Integer(1));
153	      new_region.insert(new_region.begin(), accessed_version);
154	      return BufferRegion(new_buffer, new_region);
155	    }
156	    return buffer_region;
157	  }
158	
159	  PrimExpr RewriteBufferAccess(const Call &call,
160	                               const std::vector<int> arg_indices) {
161	    auto product = [](const Array<PrimExpr> &input) {
162	      return foldl(
163	          [](PrimExpr a, PrimExpr b, Span span) { return mul(a, b, span); },
164	          make_const(DataType::Int(32), 1), input);
165	    };
166	    Array<PrimExpr> new_args = call->args;
167	    for (int i : arg_indices) {
168	      const Buffer &buffer =
169	          buffer_data_to_buffer_.at(Downcast<Var>(call->args[i]));
170	      auto it = buffer_remap_.find(buffer);
171	      if (it != buffer_remap_.end()) {
172	        const Buffer &new_buffer = (*it).second;
173	        const PrimExpr &old_index = call->args[i + 1];
174	        PrimExpr offset;
175	        if (new_buffer->strides.empty()) {
176	          offset = product(buffer->shape);
177	        } else {
178	          offset = new_buffer->strides[0];
179	        }
180	        PrimExpr new_index =
181	            old_index +
182	            floormod(pipeline_loop_->loop_var, new_buffer->shape[0]) * offset;
183	        new_args.Set(i + 1, new_index);
184	      }
185	    }
186	    return Call(call->dtype, call->op, new_args, call->span);
187	  }
188	
189	  Stmt VisitStmt_(const BlockNode *op) final {
190	    for (const Buffer &alloc_buffer : op->alloc_buffers) {
191	      buffer_data_to_buffer_.Set(alloc_buffer->data, alloc_buffer);
192	    }
193	    Block block = Downcast<Block>(StmtExprMutator::VisitStmt_(op));
194	    BlockNode *n = block.CopyOnWrite();
195	    n->reads.MutateByApply([this](const BufferRegion &buffer_region) {
196	      return RewritePipelineBufferRegion(buffer_region);
197	    });
198	    n->writes.MutateByApply([this](const BufferRegion &buffer_region) {
199	      return RewritePipelineBufferRegion(buffer_region);
200	    });
201	    for (const Buffer &alloc_buffer : op->alloc_buffers) {
202	      buffer_data_to_buffer_.erase(alloc_buffer->data);
203	    }
204	    return std::move(block);
205	  }
206	
207	  Stmt VisitStmt_(const BufferStoreNode *op) final {
208	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
209	    auto it = buffer_remap_.find(store->buffer);
210	    if (it == buffer_remap_.end()) {
211	      return std::move(store);
212	    }
213	    const Buffer &new_buffer = (*it).second;
214	    auto *n = store.CopyOnWrite();
215	    n->buffer = new_buffer;
216	    PrimExpr version = floormod(
217	        (pipeline_loop_->loop_var - pipeline_loop_->min), new_buffer->shape[0]);
218	    n->indices.insert(n->indices.begin(), version);
219	    return std::move(store);
220	  }
221	
222	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
223	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
224	    auto it = buffer_remap_.find(load->buffer);
225	    if (it == buffer_remap_.end()) {
226	      return std::move(load);
227	    }
228	    const Buffer &new_buffer = (*it).second;
229	    auto *n = load.CopyOnWrite();
230	    n->buffer = new_buffer;
231	    PrimExpr version = floormod(
232	        (pipeline_loop_->loop_var - pipeline_loop_->min), new_buffer->shape[0]);
233	    n->indices.insert(n->indices.begin(), version);
234	    return std::move(load);
235	  }
236	
237	  PrimExpr VisitExpr_(const CallNode *op) final {
238	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
239	    if (call->op.same_as(builtin::tvm_access_ptr())) {
240	      return RewriteBufferAccess(call, {1});
241	    }
242	    return call;
243	  }
244	
245	  Map<Var, Buffer> buffer_data_to_buffer_;
246	  Map<Buffer, Buffer> buffer_remap_;
247	  For pipeline_loop_;
248	  bool access_all_versions_;
249	};
