251	/*!
252	 * \brief Rewriter for the software pipeline that rewrite a loop into a
253	 * pipelined one.
254	 */
255	class PipelineRewriter : public StmtExprMutator {
256	public:
257	  PipelineRewriter(Map<Var, Buffer> buffer_data_to_buffer,
258	                   const Array<Buffer> &pipeline_allocs,
259	                   const For &pipeline_loop, const PipelineInfo &pipeline_info,
260	                   PrimExpr predicate_condition = PrimExpr())
261	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)),
262	        pipeline_allocs_(pipeline_allocs), pipeline_loop_(pipeline_loop),
263	        pipeline_info_(pipeline_info),
264	        predicate_condition_(predicate_condition) {}
265	
266	  std::pair<Stmt, Map<Var, PrimExpr>> BuildPipeline() {
267	    // Step 1: Analyze accesses to the buffers in the pipeline and compute the
268	    // number of versions need to maintain for each buffer.
269	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
270	        infos = GetBufferAccessInfo();
271	    for (const Buffer &buffer : pipeline_allocs_) {
272	      int num_versions = ComputeBufferVersions(buffer, infos.at(buffer));
273	      if (num_versions > 1) {
274	        buffer_remap_.Set(buffer, RewriteAllocBuffer(buffer, num_versions));
275	      }
276	    }
277	
278	    ordered_stmts_.resize(pipeline_info_.size());
279	    for (const auto &[block, anno] : pipeline_info_) {
280	      ordered_stmts_.Set(anno.order, block);
281	    }
282	
283	    for (const Block &block : ordered_stmts_) {
284	      int stage = pipeline_info_[block].stage;
285	      if (pipeline_info_[block].async) {
286	        auto &state = async_states[stage];
287	        state.producer_head = pipeline_loop_->min - 1;
288	        for (auto write_region : block->writes) {
289	          auto buffer = write_region->buffer;
290	          state.dst_buffers.insert(buffer.get());
291	          if (buffer_remap_.count(buffer))
292	            state.dst_buffers.insert(buffer_remap_[buffer].get());
293	        }
294	      }
295	    }
296	    std::unordered_set<int> consumed;
297	    for (const Block &block : ordered_stmts_) {
298	      int stage = pipeline_info_[block].stage;
299	      if (pipeline_info_[block].async) {
300	        auto &state = async_states[stage];
301	        if (state.commit_groups.empty() || consumed.count(stage)) {
302	          state.commit_groups.push_back({});
303	        }
304	        state.commit_groups.back().push_back(pipeline_info_[block].order);
305	        consumed.erase(stage);
306	        for (auto write_region : block->writes) {
307	          auto buffer = buffer_remap_.count(write_region->buffer)
308	                            ? buffer_remap_[write_region->buffer]
309	                            : write_region->buffer;
310	          state.buffer_to_commit_group_[buffer.get()] =
311	              state.commit_groups.size() - 1;
312	        }
313	      }
314	
315	      for (auto read_region : block->reads) {
316	        for (const auto &[producer_stage_id, producer_state] : async_states) {
317	          if (producer_stage_id <= stage &&
318	              producer_state.writes(read_region->buffer)) {
319	            consumed.insert(producer_stage_id);
320	          }
321	        }
322	      }
323	    }
324	
325	    // Step 2: Emit the pipeline prologue, body and epilogue.
326	    Stmt prologue = EmitImpl(pipeline_loop_->min,
327	                             pipeline_loop_->min + max_stage_, true, true);
328	    Stmt body =
329	        EmitImpl(pipeline_loop_->min + max_stage_,
330	                 pipeline_loop_->min + pipeline_loop_->extent, false, false);
331	    Stmt epilogue = EmitImpl(
332	        pipeline_loop_->min + pipeline_loop_->extent,
333	        pipeline_loop_->min + pipeline_loop_->extent + max_stage_, true, true);
334	
335	    SeqStmt stmt = SeqStmt({prologue, body, epilogue});
336	
337	    // Step 3: Make a new block that contains new buffer allocations after
338	    // pipeline rewriting.
339	    Array<Buffer> alloc_buffers;
340	    Map<Var, PrimExpr> buffer_versions;
341	    for (const auto &alloc : pipeline_allocs_) {
342	      int num_versions = 1;
343	      if (buffer_remap_.count(alloc)) {
344	        if (auto it = infos.find(alloc); it != infos.end()) {
345	          num_versions = ComputeBufferVersions(alloc, it->second);
346	        }
347	      }
348	      buffer_versions.Set(alloc->data, Integer(num_versions));
349	
350	      alloc_buffers.push_back(buffer_remap_.Get(alloc).value_or(alloc));
351	      buffer_data_to_buffer_.erase(alloc->data);
352	    }
353	    Block block = MakeBlock(stmt, buffer_data_to_buffer_);
354	    block.CopyOnWrite()->alloc_buffers = std::move(alloc_buffers);
355	
356	    //todo:
357	    // // === 新增：将版本信息添加到block属性中 ===
358	    // auto block_ptr = block.CopyOnWrite();
359	    // // 获取现有annotations或创建新的
360	    // auto annotations =
361	    //     block_ptr->annotations.defined()
362	    //         ? Downcast<Map<String, ObjectRef>>(block_ptr->annotations)
363	    //         : Map<String, ObjectRef>();
364	    // // 添加版本信息
365	    // annotations.Set("pipeline_buffer_versions", buffer_versions);
366	    // block_ptr->annotations = annotations;
367	
368	    // return BlockRealize({}, Bool(true), block);
369	    return {BlockRealize({}, Bool(true), block), buffer_versions};
370	  }
371	
372	private:
373	  /*!
374	   * \brief Analyze accesses to the buffers in the software pipeline.
375	   *
376	   * This method check the 'define' and 'use' stage of the buffers in the
377	   * software pipeline, which can be used to compute the number of versions
378	   * needed to maintain after rewriting.
379	   */
380	  std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
381	  GetBufferAccessInfo() {
382	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
383	        infos;
384	    for (const auto &pair : pipeline_info_) {
385	      const Block &block = pair.first;
386	      int stage = pair.second.stage;
387	      max_stage_ = std::max(max_stage_, stage);
388	
389	      for (const BufferRegion &write : block->writes) {
390	        if (!infos.count(write->buffer)) {
391	          infos.emplace(write->buffer, BufferAccessInfo{});
392	        }
393	        auto &info = infos.at(write->buffer);
394	        if (info.def == -1) {
395	          info.def = stage;
396	        } else {
397	          info.def = std::min(info.def, stage);
398	        }
399	      }
400	
401	      for (const BufferRegion &read : block->reads) {
402	        if (!infos.count(read->buffer)) {
403	          infos.emplace(read->buffer, BufferAccessInfo{});
404	        }
405	        auto &info = infos.at(read->buffer);
406	        info.use = std::max(info.use, stage);
407	      }
408	    }
409	    return infos;
410	  }
411	
412	  /*!
413	   * \brief Check whether two regions have intersections.
414	   * \param region1 The first region.
415	   * \param region2 The second region.
416	   * \return Whether region1 and region2 have intersections.
417	   */
418	  bool MayConflict(Region region1, Region region2) {
419	    ICHECK(region1.size() == region2.size());
420	    for (size_t i = 0; i < region1.size(); i++) {
421	      Range dim1 = region1[i];
422	      Range dim2 = region2[i];
423	      auto int_set1 = arith::IntSet::FromRange(dim1);
424	      auto int_set2 = arith::IntSet::FromRange(dim2);
425	      if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
426	        return false;
427	      }
428	    }
429	    return true;
430	  }
431	
432	  /*!
433	   * \brief Compute the number of versions need to maintain for buffer accessed
434	   * in the software pipeline.
435	   *
436	   * This method applies liveness analysis to the target buffer to compute the
437	   * number of versions need to maintain during the software pipeline.
438	   * Annotation `attr::double_buffer_scope` is handled here which provides a way
439	   * to override the result of the analysis. Additional double buffering in the
440	   * software pipeline can be useful to eliminate synchronizations in GPU
441	   * devices.
442	   *
443	   * \param buffer The target buffer
444	   * \param buffer_info The access information of the target buffer.
445	   * \return The number of versions required for the target buffer.
446	   */
447	  int ComputeBufferVersions(const Buffer &buffer,
448	                            const BufferAccessInfo &buffer_info) {
449	    if (buffer_info.def == -1) {
450	      // Keep the original number of versions as buffers defined outside the
451	      // software pipeline should not be mutated.
452	      return 1;
453	    }
454	
455	    // `use - def + 1` is a upper bound of the needed versions
456	    // We optimize a few case where the number of versions can be smaller than
457	    // the upper bound
458	    int num_versions = buffer_info.use - buffer_info.def + 1;
459	    if (num_versions >= 2) {
460	      // A special case when `use - def + 1 == 2`. Double buffering is only
461	      // needed in this case when these exists a reader block_i and a writer
462	      // block_j such that order(block_i) < order(block_j) and stage(block_i) <
463	      // stage(block_j) and the access regions of block_i and block_j overlap.
464	      bool need_multi_version = false;
465	      for (const auto &pair1 : pipeline_info_) {
466	        const Block &writer_block = pair1.first;
467	        const auto &writer_info = pair1.second;
468	
469	        auto it1 = std::find_if(writer_block->writes.begin(),
470	                                writer_block->writes.end(),
471	                                [&](const BufferRegion &buffer_region) {
472	                                  return buffer_region->buffer.same_as(buffer);
473	                                });
474	        if (it1 == writer_block->writes.end()) {
475	          continue;
476	        }
477	
478	        for (const auto &pair2 : pipeline_info_) {
479	          const Block &reader_block = pair2.first;
480	          const auto &reader_info = pair2.second;
481	          auto it2 = std::find_if(
482	              reader_block->reads.begin(), reader_block->reads.end(),
483	              [&](const BufferRegion &buffer_region) {
484	                return buffer_region->buffer.same_as(buffer);
485	              });
486	          if (it2 == reader_block->reads.end()) {
487	            continue;
488	          }
489	          if (writer_info.order < reader_info.order &&
490	              writer_info.stage < reader_info.stage &&
491	              MayConflict((*it1)->region, (*it2)->region)) {
492	            need_multi_version = true;
493	            break;
494	          }
495	        }
496	      }
497	      if (!need_multi_version) {
498	        num_versions--;
499	      }
500	    }
501	    return num_versions;
502	  }
503	
504	  /*!
505	   * \brief Rewrite buffer allocation to keep multiple versions of original
506	   * buffer for pipelined accesses. \param buffer The buffer to be resized.
507	   * \param num_versions The number of versions to keep.
508	   * \return The resized buffer.
509	   */
510	  Buffer RewriteAllocBuffer(const Buffer &buffer, int num_versions) {
511	    ObjectPtr<BufferNode> new_buffer = make_object<BufferNode>(*(buffer.get()));
512	    new_buffer->shape.insert(new_buffer->shape.begin(), PrimExpr(num_versions));
513	    if (new_buffer->strides.size()) {
514	      ICHECK(new_buffer->strides.size() + 1 == new_buffer->shape.size());
515	      PrimExpr stride_0 = new_buffer->strides[0] * new_buffer->shape[1];
516	      new_buffer->strides.insert(new_buffer->strides.begin(), stride_0);
517	    }
518	    return Buffer(new_buffer);
519	  }
520	
521	  // Per-stage states that need to be tracked across pipeline prologue, body,
522	  // and epilogue.
523	  struct AsyncStateGlobal {
524	    // Buffers that this stage asynchronously writes.
525	    std::unordered_set<const BufferNode *> dst_buffers;
526	    // An imaginary index that the latest async operation associated with this
527	    // stage has written into. Only valid if all associated predicates are true,
528	    // so that we can count the number of async invocations exactly. When it is
529	    // valid, it is the "sum of extents of loops that have been executed" - 1,
530	    // e.g. for epilogue it is prologue extent + body extent - 1. This is only
531	    // needed to compute wait count for epilogue without async producers.
532	    PrimExpr producer_head;
533	    std::vector<std::vector<int>> commit_groups;
534	    std::unordered_map<const BufferNode *, int> buffer_to_commit_group_;
535	    bool writes(Buffer buf) const { return dst_buffers.count(buf.get()) > 0; }
536	  };
537	
538	  // Per-stage states that are local to each of pipeline prologue, body, and
539	  // epilogue.
540	  struct AsyncStateLocal {
541	    struct PendingWait {
542	      // The index into a list of blocks, where async_wait_queue should be
543	      // attached at the beginning.
544	      int insert_before;
545	      // in_flight_count would be a more precise name, but the implementation
546	      // uses wait_count for brevity.
547	      PrimExpr wait_count{nullptr};
548	
549	      bool valid() const { return wait_count.defined(); }
550	    };
551	
552	    std::vector<PendingWait> pending_waits;
553	
554	    // A symbolic expression representing the index the latest async operation
555	    // associated with this stage has written into, at the "current" iteration.
556	    Optional<PrimExpr> producer_head;
557	  };
558	
559	  /*! Structure holding intermediate information for pipeline loop rewriting. */
560	  struct RewrittenBlockInfo {
561	    int stage;
562	    int order;
563	    PrimExpr predicate;
564	    Block block;
565	    PrimExpr access_index;
566	    bool is_async;
567	  };
568	
569	  void PopulateWaitCounts(const std::vector<RewrittenBlockInfo> &new_blocks,
570	                          std::map<int, AsyncStateLocal> *async_states_local) {
571	    for (size_t i = 0; i < new_blocks.size(); ++i) {
572	      int producer_stage_idx = -1;
573	      for (auto read_region : new_blocks[i].block->reads) {
574	        for (const auto &[stage, state] : async_states) {
575	          if (stage <= new_blocks[i].stage &&
576	              state.writes(read_region->buffer)) {
577	            // Found an earlier stage where read_region->buffer was
578	            // asynchronously written
579	            ICHECK(producer_stage_idx == -1 || producer_stage_idx == stage)
580	                << "A dependency on multiple async stages is not supported";
581	            producer_stage_idx = stage;
582	          }
583	        }
584	      }
585	      if (producer_stage_idx == -1)
586	        continue;
587	      const auto &state = async_states[producer_stage_idx];
588	      auto &dep_local_state = (*async_states_local)[producer_stage_idx];
589	      PrimExpr in_flight_cnt = 0;
590	      for (const auto &group : state.commit_groups) {
591	        PrimExpr consumer_head = new_blocks[i].access_index;
592	        PrimExpr producer_head;
593	        if (dep_local_state.producer_head.defined()) {
594	          producer_head = dep_local_state.producer_head.value();
595	          // if the group is after the wait point, minus by 1
596	          if (group.front() > new_blocks[i].order)
597	            producer_head -= 1;
598	        } else {
599	          producer_head = state.producer_head;
600	        }
601	        in_flight_cnt += producer_head - consumer_head;
602	      }
603	
604	      // We can relax the in-flight-count by the number of independent commit.
605	      std::unordered_set<int> dependent_groups;
606	      for (const auto &read_region : new_blocks[i].block->reads) {
607	        if (state.buffer_to_commit_group_.count(read_region->buffer.get()))
608	          dependent_groups.insert(
609	              state.buffer_to_commit_group_.at(read_region->buffer.get()));
610	      }
611	      for (int i = int(state.commit_groups.size()) - 1; i >= 0; i--) {
612	        if (dependent_groups.count(i) == 0)
613	          in_flight_cnt += 1;
614	        else
615	          break; // stop relaxing
616	      }
617	      in_flight_cnt = analyzer_.Simplify(in_flight_cnt);
618	      dep_local_state.pending_waits.push_back(
619	          {static_cast<int>(i), in_flight_cnt});
620	    }
621	  }
622	
623	  // Given pipelined blocks and async-related information, generate final loop
624	  // statements with async scopes (if any).
625	  Array<Stmt> CompletePipelineLoopStatements(
626	      const std::vector<RewrittenBlockInfo> &blocks,
627	      const std::map<int, AsyncStateLocal> &async_states_local) const {
628	    std::vector<RewrittenBlockInfo> new_blocks = blocks;
629	    for (const auto &[stage_id, state] : async_states_local) {
630	      for (const auto &pw : state.pending_waits) {
631	        auto &block = new_blocks[pw.insert_before].block;
632	        BlockNode *n = block.CopyOnWrite();
633	        auto zero = make_zero(DataType::Int(32));
634	        n->body = AttrStmt(zero, tir::attr::async_wait_queue_scope, stage_id,
635	                           AttrStmt(zero, tir::attr::async_wait_inflight_count,
636	                                    pw.wait_count, n->body));
637	      }
638	    }
639	
640	    // mark the last async stmt as commit
641	    std::unordered_set<int> commit_group_indices;
642	    for (const auto &[stage_id, state] : async_states) {
643	      for (size_t i = 0; i < state.commit_groups.size(); ++i) {
644	        commit_group_indices.insert(state.commit_groups[i].back());
645	      }
646	    }
647	
648	    Array<Stmt> stmts;
649	
650	    for (size_t i = 0; i < new_blocks.size(); i++) {
651	      Block block = new_blocks[i].block;
652	      if (commit_group_indices.count(new_blocks[i].order)) {
653	        auto commit_queue_scope = AttrStmt(make_zero(DataType::Int(32)),
654	                                           tir::attr::async_commit_queue_scope,
655	                                           new_blocks[i].stage, block->body);
656	        block = MakeBlock(commit_queue_scope, buffer_data_to_buffer_);
657	      }
658	      stmts.push_back(BlockRealize({}, new_blocks[i].predicate, block));
659	    }
660	
661	    return stmts;
662	  }
663	
664	  /*!
665	   * \brief Emit the pipeline loop in the given range.
666	   * \param start The start of the range
667	   * \param end The end of the range
668	   * \param unroll_loop Whether the loop should be unrolled.
669	   * \return The result loop.
670	   */
671	  Stmt EmitImpl(PrimExpr start, PrimExpr end, bool unroll_loop,
672	                bool need_bound_check) {
673	    PrimExpr new_loop_var;
674	    PrimExpr extent = end - start;
675	    auto make_nop = []() {
676	      return BlockRealize({}, Bool(true), MakeBlock(Evaluate(0), {}));
677	    };
678	
679	    bool is_unit_loop = analyzer_.CanProveEqual(extent, 1);
680	    if (is_unit_loop) {
681	      new_loop_var = start; // use constants as the loop var for unit loops
682	    } else {
683	      new_loop_var = pipeline_loop_->loop_var.copy_with_suffix("");
684	      analyzer_.Bind(Downcast<Var>(new_loop_var), Range(start, end));
685	    }
686	
687	    std::vector<RewrittenBlockInfo> new_blocks;
688	
689	    // Async related
690	    std::map<int, AsyncStateLocal> async_states_local;
691	    PrimExpr normalized_access_index;
692	
693	    for (const Block &block : ordered_stmts_) {
694	      int stage = pipeline_info_.at(block).stage;
695	      int order = pipeline_info_.at(block).order;
696	      PrimExpr inbound = Bool(true);
697	      PrimExpr skewed_loop_var = new_loop_var - stage;
698	      if (need_bound_check)
699	        inbound =
700	            analyzer_.Simplify(pipeline_loop_->min <= skewed_loop_var) &&
701	            (skewed_loop_var < pipeline_loop_->min + pipeline_loop_->extent);
702	      if (analyzer_.CanProve(!inbound)) {
703	        continue;
704	      }
705	      Block new_block = Downcast<Block>(
706	          PipelineBodyRewriter(buffer_data_to_buffer_, buffer_remap_,
707	                               pipeline_loop_, max_stage_ != 1)(block));
708	
709	      PrimExpr delta = start - pipeline_loop_->min;
710	      // This variable corresponds to
711	      // - "producer_head" if this stage is an async producer
712	      // - "consumer_head" if this stage reads from asynchronously written
713	      // buffers.
714	      normalized_access_index =
715	          is_unit_loop ? skewed_loop_var : skewed_loop_var + delta;
716	
717	      // Adjust the block predicate and the body according to the final loop
718	      // bound
719	      //  [pipeline_loop_->min, extent).
720	      if (!is_unit_loop) {
721	        Var loop_iter = Downcast<Var>(new_loop_var);
722	        inbound = Substitute(inbound, {{loop_iter, loop_iter + delta}});
723	      }
724	      new_block = Downcast<Block>(Substitute(
725	          new_block, {{pipeline_loop_->loop_var, normalized_access_index}}));
726	      if (predicate_condition_.defined()) {
727	        BlockNode *n = new_block.CopyOnWrite();
728	        n->body = IfThenElse(
729	            Substitute(predicate_condition_,
730	                       {{pipeline_loop_->loop_var, normalized_access_index}}),
731	            n->body);
732	      }
733	      if (pipeline_info_[block].async) {
734	        auto &local_state = async_states_local[stage];
735	        local_state.producer_head = normalized_access_index;
736	        BlockNode *n = new_block.CopyOnWrite();
737	        n->body = AttrStmt(make_zero(DataType::Int(32)), tir::attr::async_scope,
738	                           1, n->body);
739	      }
740	
741	      new_blocks.push_back({stage, order, inbound, new_block,
742	                            normalized_access_index,
743	                            pipeline_info_[block].async});
744	    }
745	
746	    PopulateWaitCounts(new_blocks, &async_states_local);
747	
748	    auto stmts = CompletePipelineLoopStatements(new_blocks, async_states_local);
749	
750	    Stmt new_loop{nullptr};
751	
752	    if (stmts.empty()) {
753	      return make_nop();
754	    }
755	
756	    if (stmts.size() == 1) {
757	      new_loop = stmts[0];
758	    } else {
759	      new_loop = SeqStmt(stmts);
760	    }
761	
762	    if (!is_unit_loop) {
763	      Map<String, ObjectRef> preserved_annotations;
764	      for (const auto &kv : pipeline_loop_->annotations) {
765	        const String &key = kv.first;
766	        if (kv.first != tir::attr::software_pipeline_stage &&
767	            kv.first != tir::attr::software_pipeline_order &&
768	            kv.first != tir::attr::software_pipeline_async_stages) {
769	          preserved_annotations.Set(key, kv.second);
770	        }
771	      }
772	      new_loop = For(Downcast<Var>(new_loop_var), pipeline_loop_->min, extent,
773	                     unroll_loop ? ForKind::kUnrolled : pipeline_loop_->kind,
774	                     std::move(new_loop), NullOpt, preserved_annotations);
775	    }
776	    // Update producer heads in the global async states.
777	    for (const auto &[stage_id, state] : async_states_local) {
778	      async_states[stage_id].producer_head += extent;
779	    }
780	
781	    return BlockRealize({}, Bool(true),
782	                        MakeBlock(std::move(new_loop), buffer_data_to_buffer_));
783	  }
784	
785	  arith::Analyzer analyzer_;
786	  Map<Var, Buffer> buffer_data_to_buffer_;
787	  Array<Buffer> pipeline_allocs_;
788	  For pipeline_loop_;
789	  PipelineInfo pipeline_info_;
790	  PrimExpr predicate_condition_;
791	  int max_stage_ = -1;
792	  Map<Buffer, Buffer> buffer_remap_;
793	  Array<Block> ordered_stmts_;
794	  std::map<int, AsyncStateGlobal> async_states;
795	};
796	
797	/*!
798	 * \brief Build the dependency graph among a array of blocks.
799	 * \param[in] blocks The array of blocks.
800	 * \param[out] dep_src2dst Optional, a map to store dependency edges from the
801	 * source to the destination. \param[out] dep_dst2src Optional, a map to store
802	 * dependency edges from the destination to the source.
803	 */
804	void BuildDependencyGraph(const Array<Block> &blocks,
805	                          std::unordered_map<Block, Array<Block>, ObjectPtrHash,
806	                                             ObjectPtrEqual> *dep_src2dst,
807	                          std::unordered_map<Block, Array<Block>, ObjectPtrHash,
808	                                             ObjectPtrEqual> *dep_dst2src) {
809	  std::unordered_map<Var, Array<Block>, ObjectPtrHash, ObjectPtrEqual>
810	      buffer_writers;
811	
812	  for (const Block &block : blocks) {
813	    for (const BufferRegion &read : block->reads) {
814	      auto it = buffer_writers.find(read->buffer->data);
815	      if (it != buffer_writers.end()) {
816	        for (const Block &writer : it->second) {
817	          if (dep_src2dst != nullptr) {
818	            (*dep_src2dst)[writer].push_back(block);
819	          }
820	          if (dep_dst2src != nullptr) {
821	            (*dep_dst2src)[block].push_back(writer);
822	          }
823	        }
824	      }
825	    }
826	    for (const BufferRegion &write : block->writes) {
827	      buffer_writers[write->buffer->data].push_back(block);
828	    }
829	  }
830	}
831	
832	class PipelineInjector : private StmtExprMutator {
833	public:
834	  static Stmt Inject(PrimFunc &func) {
835	    auto global_symbol = func->GetAttr<String>(tvm::attr::kGlobalSymbol);
836	    PipelineInjector injector(global_symbol);
837	    for (const auto &kv : func->buffer_map) {
838	      const Buffer &buffer = kv.second;
839	      injector.buffer_data_to_buffer_.Set(buffer->data, buffer);
840	    }
841	    Stmt result = injector(func->body);
842	
843	    if (!injector.collected_buffer_versions_.empty()) {
844	      PrimFuncNode* fptr = func.CopyOnWrite();
845	      auto fn_attr = fptr->attrs.CopyOnWrite();
846	      fn_attr->dict.Set("buffer_versions", injector.collected_buffer_versions_);
847	    }
848	
849	    return result;
850	  }
851	  
852	private:
853	  explicit PipelineInjector(Optional<String> global_symbol)
854	      : global_symbol_(global_symbol) {}
855	
856	  /*!
857	   * \brief Check the pipeline satisfies the following conditions:
858	   * 1. No conflicting order: The order of each statement should be unique.
859	   * 2. Reordering of statements doesn't break buffer access dependencies.
860	   * Specifically, for dependency (e.g. read-after-write) from statement A to
861	   * statement B, it requires: case 1: stage(A) < stage(B) case 2: stage(A) ==
862	   * stage(B) and order(A) < order(B)
863	   */
864	  void ValidatePipelineBody(const PipelineInfo &pipeline_info,
865	                            const Array<Block> &original_order) {
866	    std::unordered_set<int> used_orders;
867	    std::unordered_map<int, int> stage_max_order;
868	    std::unordered_map<int, const Block *> order_to_block;
869	    std::unordered_map<const Block *, int> block_to_stage;
870	    for (const Block &block : original_order) {
871	      const auto &stmt_info = pipeline_info.at(block);
872	      int order = stmt_info.order;
873	      CHECK(!used_orders.count(order))
874	          << "ValueError: Two statements in the software pipeline cannot have "
875	             "the same order";
876	      used_orders.insert(order);
877	    }
878	
879	    std::unordered_map<Block, Array<Block>, ObjectPtrHash, ObjectPtrEqual>
880	        dep_src2dst;
881	    BuildDependencyGraph(original_order, &dep_src2dst, nullptr);
882	
883	    for (const auto &pair : dep_src2dst) {
884	      const Block &src = pair.first;
885	      const auto &src_info = pipeline_info.at(src);
886	      const Array<Block> &dsts = pair.second;
887	      for (const Block &dst : dsts) {
888	        const auto &dst_info = pipeline_info.at(dst);
889	        CHECK_LE(src_info.stage, dst_info.stage)
890	            << "ValueError: statement " << dst << " in stage " << dst_info.stage
891	            << " cannot depends on statement " << src << " in a later stage "
892	            << src_info.stage;
893	        if (src_info.stage == dst_info.stage) {
894	          CHECK_LT(src_info.order, dst_info.order)
895	              << "ValueError: two statements with buffer "
896	                 "access dependency in the same stage of the "
897	                 "software pipeline cannot be reordered";
898	        }
899	      }
900	    }
901	  }
902	
903	  Stmt VisitStmt_(const ForNode *op) final {
904	    // Step 1: Recursively rewrite the children first.
905	    For for_node = Downcast<For>(StmtExprMutator::VisitStmt_(op));
906	    if (!HasPipelineAnnotation(op)) {
907	      return std::move(for_node);
908	    }
909	    // Step 2: Find the body and buffer allocations of the pipeline. The body
910	    // can be direct child of the for-loop. If the for-loop has BlockRealize as
911	    // its child, the pipeline body will be the child of the block.
912	    Stmt pipeline_body{nullptr};
913	    PrimExpr predicate_condition{nullptr};
914	    Array<Buffer> pipeline_allocs;
915	    if (const auto *realize = for_node->body.as<BlockRealizeNode>()) {
916	      const auto &block = realize->block;
917	      for (const auto &buffer : block->alloc_buffers) {
918	        ICHECK(buffer->IsInstance<BufferNode>());
919	        buffer_data_to_buffer_.Set(buffer->data, buffer);
920	      }
921	      if (const auto *if_then_else = block->body.as<IfThenElseNode>()) {
922	        ICHECK(!if_then_else->else_case.defined())
923	            << "Pipeline_Planning: Can't handle the body of the loop because "
924	               "it is not a SeqStmt";
925	        pipeline_body = if_then_else->then_case;
926	        predicate_condition = if_then_else->condition;
927	      } else {
928	        pipeline_body = block->body;
929	      }
930	      pipeline_allocs = block->alloc_buffers;
931	    } else {
932	      pipeline_body = for_node->body;
933	    }
934	
935	    const SeqStmtNode *pipeline_body_seq = pipeline_body.as<SeqStmtNode>();
936	    CHECK(pipeline_body_seq) << "ValueError: The body of the software pipeline "
937	                                "should be SeqStmt, got "
938	                             << pipeline_body->GetTypeKey();
939	
940	    // Step 3: Blockize the components of the pipeline. Each child of the
941	    // pipelined loop will be converted into a block.
942	    PipelineInfo pipeline_info;
943	    Array<Block> original_order; // pipeline body blocks in the original order
944	
945	    auto f_add_child = [&](const Stmt &child) {
946	      original_order.push_back(MakeBlock(child, buffer_data_to_buffer_));
947	    };
948	    for (size_t i = 0; i < pipeline_body_seq->seq.size(); i++) {
949	      const auto *nested_block_realize =
950	          pipeline_body_seq->seq[i].as<BlockRealizeNode>();
951	      if (nested_block_realize && is_one(nested_block_realize->predicate) &&
952	          nested_block_realize->block->body->IsInstance<SeqStmtNode>()) {
953	        const Block &nested_pipeline_block = nested_block_realize->block;
954	        ICHECK(nested_pipeline_block->match_buffers
955	                   .empty()); // match_buffer should have been lowered
956	        for (const auto &buffer : nested_pipeline_block->alloc_buffers) {
957	          pipeline_allocs.push_back(buffer);
958	          buffer_data_to_buffer_.Set(buffer->data, buffer);
959	        }
960	        const auto *nested_seq = nested_pipeline_block->body.as<SeqStmtNode>();
961	        for (size_t j = 0; j < nested_seq->seq.size(); j++) {
962	          f_add_child(nested_seq->seq[j]);
963	        }
964	      } else {
965	        f_add_child(pipeline_body_seq->seq[i]);
966	      }
967	    }
968	
969	    auto pipeline_stages = Downcast<Array<Integer>>(
970	        op->annotations.at(tir::attr::software_pipeline_stage));
971	    auto pipeline_orders = Downcast<Array<Integer>>(
972	        op->annotations.at(tir::attr::software_pipeline_order));
973	    CHECK_EQ(pipeline_stages.size(), original_order.size())
974	        << "PrimFunc " << global_symbol_ << " has original order "
975	        << original_order.Map(
976	               [](const auto &block) { return block->name_hint; })
977	        << ", but pipeline annotation is " << pipeline_stages
978	        << " with different size";
979	    CHECK_EQ(pipeline_orders.size(), original_order.size())
980	        << "PrimFunc " << global_symbol_ << " has original order "
981	        << original_order.Map(
982	               [](const auto &block) { return block->name_hint; })
983	        << ", but pipeline annotation is " << pipeline_orders
984	        << " with different size";
985	
986	    std::unordered_set<int> pipeline_async_stages;
987	    if (auto annot =
988	            op->annotations.Get(tir::attr::software_pipeline_async_stages)) {
989	      for (auto s : Downcast<Array<Integer>>(annot)) {
990	        pipeline_async_stages.insert(s->value);
991	      }
992	    }
993	
994	    for (size_t i = 0; i < pipeline_stages.size(); i++) {
995	      int stage = static_cast<int>(pipeline_stages[i]->value);
996	      bool is_async =
997	          pipeline_async_stages.find(stage) != pipeline_async_stages.end();
998	      PipelineAnnotation stage_order{
999	          stage,
1000	          /*order=*/static_cast<int>(pipeline_orders[i]->value), is_async};
1001	      pipeline_info.emplace(original_order[i], stage_order);
1002	    }
1003	
1004	    ValidatePipelineBody(pipeline_info, original_order);
1005	
1006	    // Step 4: Rewrite the pipeline body.
1007	    auto [pipeline_stmt, buffer_versions] = 
1008	    // Stmt pipeline =
1009	        PipelineRewriter(buffer_data_to_buffer_, pipeline_allocs,
1010	                         GetRef<For>(op), pipeline_info, predicate_condition)
1011	            .BuildPipeline();
1012	    for (const auto &[buffer, version] : buffer_versions) {
1013	      collected_buffer_versions_.Set(buffer, version);
1014	    }
1015	
1016	    if (const auto *realize = op->body.as<BlockRealizeNode>()) {
1017	      const auto &block = realize->block;
1018	      for (const auto &buffer : block->alloc_buffers) {
1019	        buffer_data_to_buffer_.erase(buffer->data);
1020	      }
1021	    }
1022	    return pipeline_stmt;
1023	  }
1024	
1025	  Stmt VisitStmt_(const BlockNode *op) final {
1026	    for (const auto &buffer : op->alloc_buffers) {
1027	      buffer_data_to_buffer_.Set(buffer->data, buffer);
1028	    }
1029	
1030	    Block block = Downcast<Block>(StmtExprMutator::VisitStmt_(op));
1031	
1032	    for (const auto &buffer : op->alloc_buffers) {
1033	      buffer_data_to_buffer_.erase(buffer->data);
1034	    }
1035	    return std::move(block);
1036	  }
1037	
1038	  bool HasPipelineAnnotation(const ForNode *op) const {
1039	    auto it1 = op->annotations.find(tir::attr::software_pipeline_stage);
1040	    auto it2 = op->annotations.find(tir::attr::software_pipeline_order);
1041	    bool has_stage = it1 != op->annotations.end();
1042	    bool has_order = it2 != op->annotations.end();
1043	    if (has_stage && has_order) {
1044	      return true;
1045	    }
1046	    if (has_stage) {
1047	      LOG(FATAL)
1048	          << "ValueError: Stage of the software pipeline is not defined.";
1049	    }
1050	    if (has_order) {
1051	      LOG(FATAL)
1052	          << "ValueError: Order of the software pipeline is not defined.";
1053	    }
1054	    return false;
1055	  }
1056	
1057	  Map<Var, Buffer> buffer_data_to_buffer_;
1058	  Optional<String> global_symbol_;
1059	  Map<Var, PrimExpr> collected_buffer_versions_;
1060	};
1061	
1062	/*!
1063	 * \brief Transform annotated loops into pipelined one that parallelize
1064	 * producers and consumers. \return The IR transform pass.
1065	 */
1066	tir::transform::Pass InjectSoftwarePipeline() {
1067	  using namespace tir::transform;
1068	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1069	    auto *fptr = f.CopyOnWrite();
1070	    fptr->body = PipelineInjector::Inject(f);
1071	    fptr->body = ConvertSSA(std::move(fptr->body));
1072	    return f;
1073	  };
1074	  return CreatePrimFuncPass(pass_func, 0, "tl.InjectSoftwarePipeline", {});
1075	}
1076	
1077	TVM_REGISTER_GLOBAL("tl.transform.InjectSoftwarePipeline")
1078	    .set_body_typed(InjectSoftwarePipeline);
1079	
1080	} // namespace tl
1081	} // namespace tvm
