39	/*!
40	 * \brief Check whether two regions have intersections.
41	 * \param region1 The first region.
42	 * \param region2 The second region.
43	 * \return Whether region1 and region2 have intersections.
44	 */
45	bool MayConflict(Region region1, Region region2) {
46	  ICHECK(region1.size() == region2.size());
47	  for (size_t i = 0; i < region1.size(); i++) {
48	    Range dim1 = region1[i];
49	    Range dim2 = region2[i];
50	    auto int_set1 = arith::IntSet::FromRange(dim1);
51	    auto int_set2 = arith::IntSet::FromRange(dim2);
52	    if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
53	      return false;
54	    }
55	  }
56	  return true;
57	}
58	
59	/*!
60	 * \brief Detect if a statement follows the global memory copy pattern:
61	 *        1. Contains exactly one buffer store operation
62	 *        2. Source buffer must be in global memory scope
63	 *        3. Destination buffer must be in local or shared memory scope
64	 */
65	class BufferRegionCollector : public StmtExprVisitor {
66	public:
67	  BufferRegionCollector(Map<Var, Buffer> buffer_data_to_buffer)
68	      : buffer_data_to_buffer_(buffer_data_to_buffer) {}
69	
70	  Array<BufferRegion> GetReads() const { return reads_; }
71	
72	  Array<BufferRegion> GetWrites() const { return writes_; }
73	
74	  bool GetGlobalCopyPattern() const { return is_global_copy_pattern_; }
75	
76	  PrimExpr GetConditonalExpr() const { return conditonal_expr; }
77	
78	private:
79	  std::string NormalizeFunctionName(const std::string &func_name) {
80	    std::string result = func_name;
81	    size_t template_pos = result.find('<');
82	    if (template_pos != std::string::npos) {
83	      result = result.substr(0, template_pos);
84	    }
85	
86	    size_t ns_pos = result.find("tl::ascend::");
87	    if (ns_pos != std::string::npos) {
88	      result = result.substr(ns_pos + 12);
89	    }
90	
91	    return result;
92	  }
93	
94	  void VisitStmt_(const BufferStoreNode *op) final {
95	    Buffer store_buffer = op->buffer;
96	    Array<PrimExpr> indices = op->indices;
97	    // convert indices to region
98	    Array<Range> region;
99	    for (const auto &index : indices) {
100	      region.push_back(Range::FromMinExtent(index, 1));
101	    }
102	    auto store_region = BufferRegion(store_buffer, region);
103	    writes_.push_back(store_region);
104	
105	    is_global_read_ = false;
106	    this->VisitExpr(op->value);
107	    if (is_global_read_ && (store_buffer.scope() == "shared" ||
108	                            store_buffer.scope() == "shared.ub" ||
109	                            store_buffer.scope() == "shared.l1")) {
110	      is_global_copy_pattern_ = true;
111	    }
112	    is_global_read_ = false;
113	  }
114	
115	  void VisitExpr_(const BufferLoadNode *op) final {
116	    auto load_buffer = op->buffer;
117	    Array<PrimExpr> indices = op->indices;
118	    // convert indices to region
119	    Array<Range> region;
120	    for (const auto &index : indices) {
121	      region.push_back(Range::FromMinExtent(index, 1));
122	    }
123	    auto load_region = BufferRegion(load_buffer, region);
124	    reads_.push_back(load_region);
125	
126	    if (op->buffer.scope() == "global") {
127	      is_global_read_ = true;
128	    }
129	  }
130	
131	  bool is_func_in_operation_config(const CallNode *op) {
132	    bool result = false;
133	    if (auto *op_ptr = op->op.as<OpNode>()) {
134	      std::string op_name = op_ptr->name;
135	      auto config_it = GetOperationConfig().find(op_name);
136	      if (config_it != GetOperationConfig().end()) {
137	        result = true;
138	      }
139	    }
140	    return result;
141	  }
142	
143	  void VisitExpr_(const CallNode *op) final {
144	    auto args = op->args;
145	    if (op->op.same_as(builtin::address_of())) {
146	      const BufferLoad load = Downcast<BufferLoad>(op->args[0]);
147	      const BufferRegion buffer_region = BufferRegion::FullRegion(load->buffer);
148	      // because we only care about the buffer itself instead of indices
149	      reads_.push_back(buffer_region);
150	    } else if (op->op.same_as(builtin::tvm_access_ptr())) {
151	      const VarNode *buffer_var = op->args[1].as<VarNode>();
152	      ICHECK(buffer_var);
153	      auto it = buffer_data_to_buffer_.find(GetRef<Var>(buffer_var));
154	      if (it != buffer_data_to_buffer_.end()) {
155	        const Buffer &buffer = (*it).second;
156	        const BufferRegion buffer_region = BufferRegion::FullRegion(buffer);
157	        // because we only care about the buffer itself instead of indices
158	        reads_.push_back(buffer_region);
159	      }
160	    } else if (op->op.same_as(tir::builtin::if_then_else())) {
161	      // Simplify nested if_then_else
162	      // if (cond) { if (inner_cond) { inner_then_expr } else { inner_else_expr
163	      // } } else { else_expr }
164	      // => if (cond && inner_cond) { inner_then_expr } else { else_expr }
165	      const PrimExpr &cond = op->args[0];
166	      const PrimExpr &then_expr = op->args[1];
167	      const PrimExpr &else_expr = op->args[2];
168	      conditonal_expr = cond;
169	      this->VisitExpr(then_expr);
170	      this->VisitExpr(else_expr);
171	    } else if (op->op.same_as(tir::builtin::call_extern())) {
172	      std::string func_str = op->args[0].as<StringImmNode>()->value;
173	      std::string normalized_name = NormalizeFunctionName(func_str);
174	      auto config_it = GetOperationConfig().find(normalized_name);
175	      if (config_it != GetOperationConfig().end()) {
176	        const auto &config = config_it->second;
177	        for (const auto &buffer_config : config.buffer_accesses) {
178	          size_t arg_index = buffer_config.first;
179	          const std::string &access_type = buffer_config.second;
180	          if (const auto *access_ptr = op->args[arg_index + 1].as<CallNode>()) {
181	            if (access_ptr->op.same_as(builtin::tvm_access_ptr())) {
182	              const VarNode *buffer_var = access_ptr->args[1].as<VarNode>();
183	              if (buffer_var) {
184	                auto it = buffer_data_to_buffer_.find(GetRef<Var>(buffer_var));
185	                if (it != buffer_data_to_buffer_.end()) {
186	                  const Buffer &buffer = (*it).second;
187	                  const BufferRegion buffer_region =
188	                      BufferRegion::FullRegion(buffer);
189	                  if (access_type == "read") {
190	                    reads_.push_back(buffer_region);
191	                    if (buffer.scope() == "global") {
192	                      is_global_read_ = true;
193	                    }
194	                  } else if (access_type == "write") {
195	                    writes_.push_back(buffer_region);
196	                    if (is_global_read_ && (buffer.scope() == "shared" ||
197	                                            buffer.scope() == "shared.ub" ||
198	                                            buffer.scope() == "shared.l1")) {
199	                      is_global_copy_pattern_ = true;
200	                    }
201	                  }
202	                }
203	              }
204	            }
205	          }
206	        }
207	      }
208	    } else if (is_func_in_operation_config(op)) {
209	      auto *op_ptr = op->op.as<OpNode>();
210	      std::string op_name = op_ptr->name;
211	      auto config_it = GetOperationConfig().find(op_name);
212	      const auto &config = config_it->second;
213	      for (const auto &buffer_config : config.buffer_accesses) {
214	        size_t arg_index = buffer_config.first;
215	        const std::string &access_type = buffer_config.second;
216	        if (const auto *access_ptr = op->args[arg_index].as<CallNode>()) {
217	          if (access_ptr->op.same_as(builtin::tvm_access_ptr())) {
218	            const VarNode *buffer_var = access_ptr->args[1].as<VarNode>();
219	            if (buffer_var) {
220	              auto it = buffer_data_to_buffer_.find(GetRef<Var>(buffer_var));
221	              if (it != buffer_data_to_buffer_.end()) {
222	                const Buffer &buffer = (*it).second;
223	                const BufferRegion buffer_region =
224	                    BufferRegion::FullRegion(buffer);
225	                if (access_type == "read") {
226	                  reads_.push_back(buffer_region);
227	                  if (buffer.scope() == "global") {
228	                    is_global_read_ = true;
229	                  }
230	                } else if (access_type == "write") {
231	                  writes_.push_back(buffer_region);
232	                  if (is_global_read_ && (buffer.scope() == "shared" ||
233	                                          buffer.scope() == "shared.ub" ||
234	                                          buffer.scope() == "shared.l1")) {
235	                    is_global_copy_pattern_ = true;
236	                  }
237	                }
238	              }
239	            }
240	          }
241	        }
242	      }
243	
244	    } else {
245	
246	      StmtExprVisitor::VisitExpr_(op);
247	    }
248	  }
249	
250	  void VisitStmt_(const IfThenElseNode *op) final {
251	    // Skip condition
252	    this->VisitStmt(op->then_case);
253	    conditonal_expr = op->condition;
254	    if (op->else_case.defined()) {
255	      this->VisitStmt(op->else_case.value());
256	    }
257	  }
258	
259	private:
260	  Map<Var, Buffer> buffer_data_to_buffer_;
261	  Array<BufferRegion> reads_;
262	  Array<BufferRegion> writes_;
263	  bool is_global_read_ = false;
264	  bool under_buffer_store_ = false;
265	  bool is_global_copy_pattern_ = false;
266	  PrimExpr conditonal_expr;
267	};
268	
269	class PipelinePlanner : public StmtExprMutator {
270	public:
271	  static Stmt Substitute(const PrimFunc &f) {
272	    PipelinePlanner substituter;
273	    for (const auto &[_, buffer] : f->buffer_map) {
274	      substituter.buffer_data_to_buffer_.Set(buffer->data, buffer);
275	    }
276	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
277	    ICHECK(target.defined())
278	        << "Pipeline_Planning: Require the target attribute";
279	    substituter.target_ = target.value();
280	    return substituter.VisitStmt(f->body);
281	  }
282	
283	private:
284	  PipelinePlanner() = default;
285	
286	  /*! \brief Information about a pipeline stage
287	   *
288	   * \param reads Array of buffer regions read by this stage
289	   * \param writes Array of buffer regions written by this stage
290	   * \param original_order Original position of this stage in the pipeline
291	   * before reordering \param order Current position of this stage in the
292	   * pipeline after reordering (-1 if not yet assigned) \param stage Pipeline
293	   * stage number this operation belongs to (-1 if not yet assigned) \param
294	   * copy_stage Whether this stage is a memory copy operation \param
295	   * last_use_stage Last pipeline stage that uses the results of this stage (-1
296	   * if not yet determined)
297	   */
298	  struct PipelineStageInfo {
299	    Array<BufferRegion> reads, writes;
300	    int original_order;
301	    int order = -1, stage = -1;
302	    bool copy_stage = false;
303	    bool prepare_for_condition = false;
304	    int last_use_stage = -1;
305	    // represent the stage is used in a conditional statement
306	    PrimExpr conditonal_expr;
307	  };
308	
309	  PipelineStageInfo MakePipelineStageInfo(Stmt stmt, int idx) {
310	    Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{}, /*name_hint=*/"",
311	                /*body*/ stmt);
312	    Array<Array<BufferRegion>> access =
313	        GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
314	    auto collector = BufferRegionCollector(buffer_data_to_buffer_);
315	    collector(block);
316	    PipelineStageInfo pinfo;
317	    pinfo.reads = std::move(collector.GetReads());
318	    pinfo.writes = std::move(collector.GetWrites());
319	    pinfo.original_order = idx;
320	    pinfo.copy_stage = collector.GetGlobalCopyPattern();
321	    pinfo.conditonal_expr = collector.GetConditonalExpr();
322	    return std::move(pinfo);
323	  }
324	
325	  Stmt VisitStmt_(const ForNode *loop) final {
326	    auto order_anno = loop->annotations.Get("tl_pipeline_order");
327	    auto stage_anno = loop->annotations.Get("tl_pipeline_stage");
328	    auto num_stages_anno = loop->annotations.Get("num_stages");
329	    if (order_anno.defined() && stage_anno.defined()) {
330	      // Check if order_anno or stage_anno contains -1, which means TMA+WS is
331	      // enabled
332	      bool ws_tma_enabled = false;
333	      auto order_array = Downcast<Array<Integer>>(order_anno);
334	      auto stage_array = Downcast<Array<Integer>>(stage_anno);
335	      for (const auto &val : order_array) {
336	        if (val->value == -1) {
337	          ws_tma_enabled = true;
338	          break;
339	        }
340	      }
341	      if (!ws_tma_enabled) {
342	        for (const auto &val : stage_array) {
343	          if (val->value == -1) {
344	            ws_tma_enabled = true;
345	            break;
346	          }
347	        }
348	      }
349	
350	      if (ws_tma_enabled) {
351	        return StmtExprMutator::VisitStmt_(loop);
352	      }
353	
354	      Map<String, ObjectRef> annotations;
355	      for (const auto &[key, value] : loop->annotations) {
356	        if (key != "tl_pipeline_order") {
357	          annotations.Set(key, value);
358	        }
359	      }
360	      annotations.Set(tir::attr::software_pipeline_order, order_anno);
361	
362	      for (const auto &[key, value] : loop->annotations) {
363	        if (key != "tl_pipeline_stage") {
364	          annotations.Set(key, value);
365	        }
366	      }
367	      annotations.Set(tir::attr::software_pipeline_stage, stage_anno);
368	      if (TargetHasAsyncCopy(target_))
369	        annotations.Set(tir::attr::software_pipeline_async_stages,
370	                        Array<Integer>{0});
371	      auto for_node = GetRef<For>(loop);
372	      for_node.CopyOnWrite()->annotations = annotations;
373	      return for_node;
374	    }
375	
376	    if (!num_stages_anno.defined())
377	      return StmtExprMutator::VisitStmt_(loop);
378	    int num_stages = num_stages_anno.as<IntImmNode>()->value;
379	    Stmt pipeline_body{nullptr};
380	    if (const auto *realize = loop->body.as<BlockRealizeNode>()) {
381	      const auto &block = realize->block;
382	      for (const auto &buffer : block->alloc_buffers) {
383	        ICHECK(buffer->IsInstance<BufferNode>());
384	        buffer_data_to_buffer_.Set(buffer->data, buffer);
385	      }
386	      if (const auto *seq_stmt = block->body.as<SeqStmtNode>()) {
387	        pipeline_body = block->body;
388	      } else if (const auto *if_then_else = block->body.as<IfThenElseNode>()) {
389	        // should assert else case is nullptr
390	        ICHECK(!if_then_else->else_case.defined())
391	            << "Pipeline_Planning: Can't handle the body of the loop because "
392	               "it is not a SeqStmt";
393	        pipeline_body = if_then_else->then_case;
394	      } else {
395	        LOG(FATAL) << "Pipeline_Planning: Can't handle the body of the loop "
396	                      "because it is not a SeqStmt or IfThenElse";
397	      }
398	    } else {
399	      pipeline_body = loop->body;
400	    }
401	    const SeqStmtNode *pipeline_body_seq = pipeline_body.as<SeqStmtNode>();
402	    CHECK(pipeline_body_seq)
403	        << "ValueError: The body of the software pipeline "
404	           "should be SeqStmt, got "
405	        << pipeline_body->GetTypeKey() << " " << pipeline_body;
406	    CHECK(num_stages >= 1);
407	    CHECK(loop->kind == ForKind::kSerial);
408	
409	    std::vector<PipelineStageInfo> pipeline_stage_infos;
410	    for (size_t i = 0; i < pipeline_body_seq->size(); i++) {
411	      auto pinfo = MakePipelineStageInfo(pipeline_body_seq->seq[i], i);
412	      pipeline_stage_infos.push_back(std::move(pinfo));
413	    }
414	
415	    // process the conditional stage
416	    // assign conditional stage (analysis the copy stage)
417	    for (auto &pinfo : pipeline_stage_infos) {
418	      for (const auto &write : pinfo.writes) {
419	        for (const auto &other : pipeline_stage_infos) {
420	          if (other.conditonal_expr.defined()) {
421	            auto check_var = [&](const ObjectRef &n) {
422	              if (const auto *buffer_load = n.as<BufferLoadNode>()) {
423	                if (buffer_load->buffer == write->buffer) {
424	                  pinfo.prepare_for_condition = true;
425	                }
426	              }
427	            };
428	            PostOrderVisit(other.conditonal_expr, check_var);
429	          }
430	        }
431	      }
432	    }
433	
434	    // analysis use-def chain
435	    for (auto &pinfo : pipeline_stage_infos) {
436	      for (int i = pinfo.original_order + 1;
437	           i < static_cast<int>(pipeline_body_seq->size()); i++) {
438	        if (!pinfo.copy_stage)
439	          continue;
440	        for (const BufferRegion &read : pipeline_stage_infos[i].reads) {
441	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
442	                           [&](const BufferRegion &r) {
443	                             return r->buffer == read->buffer &&
444	                                    MayConflict(r->region, read->region);
445	                           }) != pinfo.writes.end()) {
446	            pinfo.last_use_stage = std::max(pinfo.last_use_stage, i);
447	          }
448	        }
449	        for (const BufferRegion &write : pipeline_stage_infos[i].writes) {
450	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
451	                           [&](const BufferRegion &r) {
452	                             return r->buffer == write->buffer &&
453	                                    MayConflict(r->region, write->region);
454	                           }) != pinfo.writes.end()) {
455	            LOG(FATAL) << "Pipeline planning error: Multiple writes to "
456	                          "overlapping buffer regions detected. "
457	                       << "Stage " << pinfo.original_order << " and stage " << i
458	                       << " are both writing to buffer '" << write->buffer->name
459	                       << "' with overlapping regions. This is not supported "
460	                          "in pipeline planning.";
461	          }
462	        }
463	      }
464	    }
465	
466	    // Making stages and orders
467	    int order_idx = 0;
468	    // Create pipeline stages and assign order
469	    for (auto &pinfo : pipeline_stage_infos) {
470	      // Skip elements that must be in first stage:
471	      // 1. Copy stages (with active last_use_stage)
472	      // 2. Condition preparation stages
473	      if ((pinfo.copy_stage && pinfo.last_use_stage != -1) ||
474	          pinfo.prepare_for_condition)
475	        continue;
476	
477	      // Main logic stage assignment:
478	      // - Increment order index
479	      // - Assign to new stage (current num_stages)
480	      pinfo.order = order_idx++;
481	      pinfo.stage = num_stages;
482	
483	      for (auto &pinfo_1 : pipeline_stage_infos) {
484	        if ((pinfo_1.copy_stage &&
485	             pinfo_1.last_use_stage == pinfo.original_order)) {
486	          pinfo_1.order = order_idx++;
487	          pinfo_1.stage = 0;
488	        }
489	      }
490	    }
491	
492	    // Handle trailing unassigned copy stages:
493	    // These are typically final copy operations needing post-main-stage
494	    // insertion
495	    auto &head_pinfo = pipeline_stage_infos.at(0);
496	    int unassigned_order_elem = -1;
497	
498	    // Process dependent copy stages:
499	    // Insert copy stages after current stage but assign to stage 0
500	    // and adjust the order index
501	    for (auto &pinfo : pipeline_stage_infos) {
502	      if (pinfo.order == unassigned_order_elem) {
503	        pinfo.order = unassigned_order_elem++;
504	        // traverse the from the next info
505	        for (auto it = pipeline_stage_infos.begin() + unassigned_order_elem;
506	             it != pipeline_stage_infos.end(); it++) {
507	          it->order += 1;
508	        }
509	        pinfo.stage = 0;
510	        order_idx++;
511	      }
512	    }
513	
514	    ICHECK(size_t(order_idx) == pipeline_stage_infos.size())
515	        << "The number of stages should be equal to the number of pipeline "
516	           "stages. "
517	        << "Got " << order_idx << " stages and " << pipeline_stage_infos.size()
518	        << " pipeline stages.";
519	
520	    // if all the copy is at the end of the order, we can move these copy to the
521	    // beginning of the order and shrink the stage offset by 1.
522	    int copy_stage_at_end = [&]() {
523	      int copy_stage_cnt = 0;
524	      int copy_order_min = pipeline_stage_infos.size();
525	      int non_copy_order_max = 0;
526	      for (auto &pinfo : pipeline_stage_infos) {
527	        if (pinfo.copy_stage || pinfo.prepare_for_condition) {
528	          copy_stage_cnt++;
529	          copy_order_min = std::min(copy_order_min, pinfo.order);
530	        } else {
531	          non_copy_order_max = std::max(non_copy_order_max, pinfo.order);
532	        }
533	      }
534	      if (copy_order_min > non_copy_order_max)
535	        return copy_stage_cnt;
536	      return -1;
537	    }();
538	    if (copy_stage_at_end > 0 && num_stages >= 2) {
539	      for (auto &pinfo : pipeline_stage_infos) { // move copy to the beginning
540	        pinfo.order =
541	            (pinfo.order + copy_stage_at_end) % pipeline_stage_infos.size();
542	        if (!pinfo.copy_stage && !pinfo.prepare_for_condition)
543	          pinfo.stage--;
544	      }
545	    }
546	
547	    // Finally, make the pipeline annotation
548	    Map<String, ObjectRef> annotations;
549	    for (const auto &[key, value] : loop->annotations) {
550	      if (key != "num_stages") {
551	        annotations.Set(key, value);
552	      }
553	    }
554	
555	    std::vector<Integer> orders, stages;
556	    orders.reserve(pipeline_stage_infos.size());
557	    stages.reserve(pipeline_stage_infos.size());
558	    for (auto &pinfo : pipeline_stage_infos) {
559	      orders.push_back(pinfo.order);
560	      stages.push_back(pinfo.stage);
561	    }
562	
563	    annotations.Set(tir::attr::software_pipeline_stage, Array<Integer>(stages));
564	    annotations.Set(tir::attr::software_pipeline_order, Array<Integer>(orders));
565	    if (TargetHasAsyncCopy(target_))
566	      annotations.Set(tir::attr::software_pipeline_async_stages,
567	                      Array<Integer>{0});
568	
569	    return For(loop->loop_var, loop->min, loop->extent, loop->kind, loop->body,
570	               loop->thread_binding, annotations);
571	  }
572	
573	  Stmt VisitStmt_(const BlockNode *op) final {
574	    for (const auto &buffer : op->alloc_buffers) {
575	      buffer_data_to_buffer_.Set(buffer->data, buffer);
576	    }
577	    Block block = Downcast<Block>(StmtExprMutator::VisitStmt_(op));
578	    for (const auto &buffer : op->alloc_buffers) {
579	      buffer_data_to_buffer_.erase(buffer->data);
580	    }
581	    return std::move(block);
582	  }
583	
584	  Map<Var, Buffer> buffer_data_to_buffer_;
585	  Target target_;
586	};
587	
588	tvm::transform::Pass PipelinePlanning() {
589	  using namespace tir::transform;
590	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
591	    PrimFuncNode *fptr = f.CopyOnWrite();
592	    fptr->body = PipelinePlanner::Substitute(f);
593	    return f;
594	  };
595	  return CreatePrimFuncPass(pass_func, 0, "tl.PipelinePlanning", {});
596	}
597	
598	TVM_REGISTER_GLOBAL("tl.transform.PipelinePlanning")
599	    .set_body_typed(PipelinePlanning);
600	
601	} // namespace tl
602	} // namespace tvm
